/*
 * A005660  If k appears so do 2k+2 and 3k+3. (duplicates omitted.)
 * https://oeis.org/A005660
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(1) = 3; the sequence is the sorted union, duplicates removed,
 *            of {3}, {2*a(k)+2} and {3*a(k)+3}. It is generated by merging
 *            the two streams with two pointers, as for Hamming numbers
 * Range:     u8 n <= 33, u16 n <= 2579, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 71 terms through n = 9265 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/mem.h"

static seq_t *zalloc_arr(idx_t len) {
    return mem_new(seq_t, (size_t)len);
}

static seq_t *grow_arr(seq_t *old, idx_t oldlen, idx_t newlen) {
    seq_t *r = mem_new(seq_t, newlen);
    idx_t i;
    for (i = 0; i < oldlen; i++) r[i] = old[i];
    if (old) mem_free(old);
    return r;
}

seq_t a(idx_t n) {
  static seq_t *cache = NULL;
  static idx_t len = 0;
  static idx_t cap = 0;
  static idx_t i = 0;
  static idx_t j = 0;

  if (cache == NULL) {
    cap = 1024;
    cache = zalloc_arr(cap);
    cache[0] = 3;
    len = 1;
  }

  while (len < n) {
    if (len >= cap) {
      cache = grow_arr(cache, cap, cap * 2);
      cap *= 2;
    }
    seq_t x = cache[i] * 2 + 2;
    seq_t y = cache[j] * 3 + 3;
    seq_t m = (x < y) ? x : y;
    cache[len++] = m;
    if (x == m) i++;
    if (y == m) j++;
  }

  return cache[n - 1];
}
